package java.util;
public class Observable {private boolean changed;private final Vector<Observer> observers=new Vector<Observer>();public synchronized void addObserver(Observer o){if(o==null)throw new NullPointerException();if(!observers.contains(o))observers.add(o);}public synchronized void deleteObserver(Observer o){observers.remove(o);}public void notifyObservers(){notifyObservers(null);}public void notifyObservers(Object arg){Object[] a;synchronized(this){if(!changed)return;a=observers.toArray();clearChanged();}for(int i=a.length-1;i>=0;i--)((Observer)a[i]).update(this,arg);}public synchronized void deleteObservers(){observers.clear();}protected synchronized void setChanged(){changed=true;}protected synchronized void clearChanged(){changed=false;}public synchronized boolean hasChanged(){return changed;}public synchronized int countObservers(){return observers.size();}}
